import {reviewForm} from './review-form.mjs?v=34';
import {livingScene} from './living-scene.mjs?v=32';
export function featuredProperties(bundle) {
 const properties=bundle.properties||[];
 if(!properties.length)return `<section class="featured-section wrap"><h2>Propiedades</h2><p>El catálogo se está actualizando. Cuéntanos qué buscas.</p>${link('contacto.html','Contactar al equipo')}</section>`;
 return `<section class="featured-section wrap" id="propiedades"><div class="module-heading"><h2>Propiedades</h2>${link('propiedades.html','Explorar el catálogo')}</div>
  <div class="featured-carousel" data-feature-index="0" data-feature-paused="false" role="region" aria-label="Propiedades destacadas">
   ${properties.map((property,index)=>`<article class="featured-slide" ${index?'hidden':''}><a class="featured-image" href="${propertyURL(property.id)}"><img src="${safeURL(imageOf(property))}" alt="${e(property.titulo)}" width="1600" height="1000" loading="lazy"></a><div class="featured-caption"><div><p>${e(property.operacion)} · ${e([property.colonia,property.municipio].filter(Boolean).join(', '))}</p><h3><a href="${propertyURL(property.id)}">${e(property.titulo)}</a></h3></div><p class="property-price">${e(money(property.precio,property.moneda))} <small>${e(property.moneda||'MXN')}</small></p></div></article>`).join('')}
   <div class="featured-controls"><span data-feature-count aria-live="off">1 / ${properties.length}</span><button class="text-button" data-feature-toggle>Pausar</button><button data-feature-direction="-1" aria-label="Propiedad anterior">${icon('arrow')}</button><button data-feature-direction="1" aria-label="Siguiente propiedad">${icon('arrow')}</button></div>
  </div>
 </section>`;
}
import {articleRoutes,propertyRoutes} from './routes.mjs';
export const e=value=>String(value??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
export function safeURL(value){const s=String(value||'');return /^(https:\/\/|assets\/|[a-z0-9-]+\.html(?:[?#]|$)|#)/i.test(s)?e(s):'#';}
const paths={arrow:'M5 12h14m-6-6 6 6-6 6',up:'M5 19 19 5M5 5h14v14',house:'m3 10 9-7 9 7v10H3Zm6 10v-7h6v7',key:'M10 13a5 5 0 1 1 3-3l8 8-3 3-2-2 2-2',calendar:'M8 3v4m8-4v4M4 11h16M5 5h14v16H5Z',check:'m5 12 4 4L19 6',search:'m16 16 5 5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',heart:'M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-4 4 1 9 8 15 7-6 12-11 8-15Z',compare:'M4 4h6v16H4Zm10 0h6v16h-6Z',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2Zm6-2v16m6-14v16',file:'M14 3H5v18h14V8Zm0 0v5h5M8 12h8m-8 4h8',chevron:'m8 5 7 7-7 7',plus:'M5 12h14m-7-7v14',clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',star:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9Z'};
export const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.arrow}"/></svg>`;
export const link=(href,label,cls='text-link')=>`<a class="${cls}" href="${safeURL(href)}">${e(label)} ${icon('arrow')}</a>`;
export const money=(n,currency='MXN')=>n?new Intl.NumberFormat('es-MX',{style:'currency',currency:['USD','MXN'].includes(currency)?currency:'MXN',maximumFractionDigits:0}).format(n):'Consultar precio';
export const plain=value=>String(value||'').replace(/<[^>]*>/g,'').trim();
export function imageOf(property){const first=property.imagenes?.[0];return typeof first==='string'?first:first?.url||'assets/property-placeholder.svg';}
export const propertyURL=id=>propertyRoutes[id]||'propiedad.html?id='+encodeURIComponent(id);
const availablePosts=data=>(data.posts||[]).filter(p=>p.published!==false);
const postURL=slug=>articleRoutes[slug]||'articulo.html?slug='+encodeURIComponent(slug);
const contactURL=intent=>'contacto.html?interes='+encodeURIComponent(intent)+'#contacto';
export function propertyCard(p){return `<article class="property-card" data-property="${e(p.id)}"><div class="property-photo"><a href="${propertyURL(p.id)}"><img src="${safeURL(imageOf(p))}" alt="${e(p.titulo)}" loading="lazy" width="700" height="480"></a><span class="property-operation">${e(p.operacion)}</span><button class="favorite-button" data-favorite="${e(p.id)}" aria-label="Guardar propiedad" aria-pressed="false">${icon('heart')}</button></div><div class="property-copy"><p class="property-location">${e([p.colonia,p.municipio].filter(Boolean).join(' · '))}</p><h3><a href="${propertyURL(p.id)}">${e(p.titulo)}</a></h3><p class="property-price">${e(money(p.precio,p.moneda))} <small>${e(p.moneda||'MXN')}</small></p><ul class="property-facts"><li>${e(p.recamaras??'—')} rec.</li><li>${e(p.banos??'—')} baños</li><li>${e(p.m2_construccion||p.m2_terreno||'—')} m²</li></ul></div></article>`;}
export function propertyModule(bundle,full=false){if(!full)return featuredProperties(bundle);return `<section class="catalog-section wrap" id="propiedades"><div class="module-heading"><div><h2>${full?'Encuentra tu próximo espacio.':'Espacios con una historia por empezar.'}</h2><p>Selección de Confort4. Consulta la disponibilidad con el equipo.</p></div>${!full?link('propiedades.html','Explorar propiedades'):''}</div><div class="catalog-meta"><span id="catalog-count" role="status">${bundle.properties.length} propiedades</span><span class="catalog-status">Inventario conectado</span></div><div id="property-grid" class="property-grid">${bundle.properties.map(propertyCard).join('')}</div><p class="catalog-disclaimer">Precios en la moneda indicada. La publicación de una propiedad no garantiza su disponibilidad al momento de la consulta.</p></section>`;}
export function intents(data) {
 const purchase = data.services.filter(service => service.id !== 'rentar');
 const rental = data.services.find(service => service.id === 'rentar');
 return `<section class="intent-section" id="servicios"><div class="wrap">
  <div class="module-heading"><h2>Cada proyecto,<br>su propio camino.</h2><p>Comprar, vender o rentar. Acompañamiento para las decisiones que vienen.</p></div>
  <div class="service-columns"><div><h3>Comprar y vender</h3>${purchase.map((service,index) => `<details class="service-choice" ${index===0?'open':''}><summary>${e(service.shortTitle)} ${icon('plus')}</summary><div><p>${e(service.intro)}</p><img src="${safeURL(service.image)}" alt="Fotografía residencial de ambientación" width="800" height="500" loading="lazy">${link(service.id+'.html','Conoce el proceso')}</div></details>`).join('')}</div>
  <div><h3>Rentar</h3>${rental.audiences.map((audience,index) => `<details class="service-choice" ${index===0?'open':''}><summary>${e(audience.title)} ${icon('plus')}</summary><div><p>${e(audience.intro)}</p><img src="assets/${index===0?'editorial-rental.jpg':'editorial-agreement.jpg'}" alt="Fotografía residencial de ambientación" width="800" height="500" loading="lazy">${link('rentar.html#'+audience.id,'Conoce el proceso')}</div></details>`).join('')}</div></div>
 </div></section>`;
}
export function processModule(data,service='general') {
 return `<section class="process-section wrap narrative-process" id="proceso">
  <div class="process-guide"><h2 class="scroll-copy">Tu proyecto marca la estrategia. Escuchamos, conectamos y te acompañamos en cada decisión.</h2></div>
  <div class="process-stages">${data.process.map((step,index) => `<article class="process-stage" data-stage="${index}">
   <figure><img src="assets/${['editorial-visit.jpg','editorial-agreement.jpg','editorial-rental.jpg'][index]}" alt="Espacio residencial de ambientación" width="1200" height="850" loading="lazy"></figure>
   <div><span class="phase-number">${index+1} / 3</span><h3>${e(step.title)}</h3><p>${e(step.text)}</p><ul>${step.items.map(item=>`<li>${e(item)}</li>`).join('')}</ul></div>
  </article>`).join('')}</div>
 </section>`;
}
export function checklist(data,key='venta'){const names={venta:'Prepara tu propiedad para vender.',visita:'Lleva mejores preguntas a tu visita.',renta:'Una entrega de renta, bien documentada.'};const items=data.checklists[key]||[];return `<section class="checklist-module" data-checklist="${key}"><div><h2>${names[key]}</h2><p>Marca lo que ya revisaste. Este listado te ayuda a organizar la conversación con el equipo.</p><button class="text-button" data-print>${icon('file')} Imprimir mi checklist</button></div><div class="checklist-items"><p class="checklist-status" role="status">0 de ${items.length} revisados</p><progress max="${items.length}" value="0" aria-label="Avance del checklist"></progress>${items.map((item,i)=>`<label><input type="checkbox" data-check="${i}"><span>${e(item)}</span></label>`).join('')}</div></section>`;}
export function faqModule(data,full=false){return `<section class="faq-module wrap"><div><h2>${full?'Respuestas para cada etapa.':'Las preguntas que sí importan.'}</h2><p>Información breve para decidir tu siguiente paso.</p><label class="faq-search">Buscar una pregunta<input type="search" id="faq-search" placeholder="Precio, documentos, renta…"></label></div><div id="faq-list">${data.faq.map(f=>`<details data-faq><summary>${e(f.question)}${icon('plus')}</summary><p>${e(f.answer)}</p></details>`).join('')}<p class="faq-empty" hidden>No encontramos esa pregunta. Cuéntanos tu duda en el formulario.</p></div></section>`;}
export function journal(data,full=false){const posts=availablePosts(data);return `<section class="journal-module wrap"><div class="module-heading"><div><h2>${full?'Ideas para decidir mejor.':'Un poco de claridad<br>para lo que sigue.'}</h2><p>Lecturas prácticas del equipo Confort4.</p></div>${full?'':link('blog.html','Todas las lecturas')}</div>${full?`<div class="journal-controls"><label>¿Qué te gustaría saber?<input type="search" id="blog-search" placeholder="¿Qué te gustaría saber?" maxlength="200"></label></div>`:''}<div class="journal-grid">${(full?posts:posts.slice(0,3)).map((post,i)=>`<article class="journal-card" data-post data-category="${e(post.category)}" data-search="${e([post.title,post.excerpt,post.category,...post.sections.flatMap(section=>[section.title,section.text])].join(' '))}"><a href="${postURL(post.slug)}"><img src="${safeURL(post.cover)}" alt="Fotografía de ambientación para ${e(post.title)}" loading="lazy" width="700" height="440"></a><div><p class="article-meta">${e(post.category)} · ${Math.max(1,Math.ceil(JSON.stringify(post.sections).split(/\s+/).length/200))} min de lectura</p><h3><a href="${postURL(post.slug)}">${e(post.title)}</a></h3><p>${e(post.excerpt)}</p>${link(postURL(post.slug),'Leer artículo')}</div></article>`).join('')}</div><div id="blog-empty" class="blog-question" role="status" hidden><h3>Esa duda te la podemos solucionar por privado.</h3><p>Envíanos tu pregunta y el equipo te ayudará. También nos servirá para preparar nuevas lecturas.</p><a class="button" id="blog-question-link" href="contacto.html">Mandarnos un mensaje ${icon('arrow')}</a></div></section>`;}
function field(name,label,type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" ${extra}><span class="field-error" data-error-for="${name}"></span></label>`;}
function kwAssociation(){return '<div class="kw-association"><span>Asociados a</span><img src="assets/kw-premier.png" alt="KW Premier" width="155" height="56" loading="lazy"></div>';}
function teamPage(bundle) {
 const d=bundle.content,t=d.team;
 return `<section class="page-intro wrap">${link('index.html','Inicio','breadcrumb')}<h1 data-team-text>${e(t.title)}</h1><div class="intro-copy"><p data-team-text>${e(t.intro)}</p>${t.paragraphs.map(text=>`<p data-team-text>${e(text)}</p>`).join('')}${kwAssociation()}</div></section>
 ${t.cover?`<figure class="team-cover wrap"><div class="team-media-frame" data-motion-image data-motion-framing="faces"><img src="${safeURL(t.cover)}" alt="Alberto y Renata Flores, equipo Confort4" width="1800" height="1200" fetchpriority="high"></div></figure>`:''}
 <section class="team-story wrap"><span class="team-rule" data-team-rule aria-hidden="true"></span><div class="team-profile-grid">${t.members.map(p=>`<article class="team-profile" id="${e(p.id)}"><div class="portrait" data-motion-image><img src="${safeURL(p.photo)}" alt="${e(p.name)}" width="680" height="1020" loading="lazy"></div><h2 data-team-text>${e(p.name)}</h2><p data-team-text>${e(p.bio||'')}</p><a class="button button-outline team-contact-button" href="${safeURL(p.contact)}" target="_blank" rel="noopener" aria-label="Contactar a ${e(p.name)} por WhatsApp">Contáctame ${icon('arrow')}</a></article>`).join('')}</div></section>
 ${t.approach?.length?`<section class="team-approach wrap"><span class="team-rule" data-team-rule aria-hidden="true"></span><h2 data-team-text>Cómo te acompañamos.</h2><div>${t.approach.map(step=>`<article><h3 data-team-text>${e(step.title)}</h3><p data-team-text>${e(step.text)}</p></article>`).join('')}</div></section>`:''}
 ${teamPhotos(d)}
 ${t.gallery?.length?`<section class="team-moments wrap"><span class="team-rule" data-team-rule aria-hidden="true"></span><h2 data-team-text>${e(t.galleryTitle||'Con nuestra comunidad.')}</h2><p data-team-text>${e(t.galleryIntro||'Momentos de Alberto y Renata con Keller Williams.')}</p><div>${t.gallery.map(photo=>`<figure><div class="team-moment-image" data-motion-image><img src="${safeURL(photo.photo)}" alt="${e(photo.caption)}" width="1000" height="1400" loading="lazy"></div><figcaption data-team-text>${e(photo.caption)}</figcaption></figure>`).join('')}</div></section>`:''}
 ${t.nationalAward?.photos?.length?`<section class="team-awards wrap"><span class="team-rule" data-team-rule aria-hidden="true"></span><div class="team-award-copy"><h2 data-team-text>${e(t.nationalAward.title)}</h2><p data-team-text>${e(t.nationalAward.description)}</p></div><div class="team-award-photos">${t.nationalAward.photos.map(photo=>`<figure><div class="team-award-image" data-motion-image><img src="${safeURL(photo.photo)}" alt="${e(photo.caption)}" width="1100" height="1800" loading="lazy"></div><figcaption data-team-text>${e(photo.caption)}</figcaption></figure>`).join('')}</div></section>`:''}
 ${reviewModule(bundle)}`;
}
function teamPhotos(data) {
 if(!data.team.photos?.length)return '';
 return `<section class="team-photo-story wrap"><span class="team-rule" data-team-rule aria-hidden="true"></span><h2 data-team-text>Alberto y Renata. Un equipo contigo.</h2><div>${data.team.photos.map(photo=>`<div class="team-media-frame" data-motion-image><img src="${safeURL(photo)}" alt="Alberto y Renata Flores, equipo Confort4" width="1800" height="1200" loading="lazy"></div>`).join('')}</div></section>`;
}
export function contactDetails(data,compact=false) {
 const members=(data.team?.members||[]).filter(p=>p.phone);
 const email=String(data.email||''),office=String(data.office||'');
 return `<div class="team-contact-links${compact?' compact':''}">${members.map(p=>`<div><span>${e(p.name.split(' ')[0])}</span><a class="button button-outline contact-direct" href="${safeURL(p.contact)}" target="_blank" rel="noopener" aria-label="WhatsApp de ${e(p.name)}">Contáctame ${icon('arrow')}</a></div>`).join('')}${email?`<a class="team-email" href="mailto:${e(encodeURIComponent(email))}">${e(email)}</a>`:''}${office?`<a class="team-office" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(office)}" target="_blank" rel="noopener"><span>Oficina</span><address>${e(office)}</address></a>`:''}</div>`;
}
export function contactForm(data={},primary=false) {
 return `<section class="contact-form-section wrap" id="contacto">
  <div class="contact-form-intro">
   <${primary?'h1':'h2'}>Hablemos de tu próximo movimiento.</${primary?'h1':'h2'}>
   <p>Comprar, vender o rentar. Cuéntanos qué tienes en mente y empecemos por ahí.</p>
   ${contactDetails(data)}
   <p class="contact-team">Alberto y Renata Flores<br>Confort4 · KW Premier</p>
  </div>
  <form method="post" class="site-form contact-single" data-kind="contact">
   <${primary?'h2':'h3'}>Cuéntanos tu proyecto</${primary?'h2':'h3'}>
   <div class="form-grid">
    ${field('name','Tu nombre','text','autocomplete="name" minlength="2" maxlength="100" required')}
    <label>Me interesa<select name="interest" required><option value="">Elige una opción</option><option value="vender">Vender una propiedad</option><option value="comprar">Comprar una propiedad</option><option value="rentar-arrendador">Poner mi propiedad en renta</option><option value="rentar-inquilino">Encontrar una propiedad en renta</option><option value="general">Otro proyecto</option></select></label>
    <label><span data-zone-label>¿Cuál es tu zona de interés? · opcional</span><input name="zone" maxlength="120" placeholder="Colonia o alcaldía"></label>
    ${field('email','Correo electrónico','email','autocomplete="email" maxlength="254" required')}
    ${field('phone','Teléfono','tel','autocomplete="tel" maxlength="30"')}
   </div>
   <label class="message-field">¿Qué te gustaría lograr?<textarea name="message" rows="3" maxlength="2000" placeholder="Cuéntanos lo que más te importa · opcional"></textarea></label>
   <label class="consent"><input type="checkbox" name="consent" required><span>Autorizo el uso de mis datos para atender mi solicitud conforme al <a href="privacidad.html">aviso de privacidad</a>.</span></label>
   <button class="button" type="submit">Contactar al equipo ${icon('arrow')}</button>
   <div class="form-trap" aria-hidden="true"><input name="website" tabindex="-1" autocomplete="off"></div>
   <p class="form-status" role="status" tabindex="-1"></p>
   <noscript><p>Activa JavaScript para enviar o escríbenos por WhatsApp.</p></noscript>
  </form>
 </section>`;
}
export function reviewModule(bundle){return `<section class="reviews-module wrap"><div class="module-heading"><div><h2>La experiencia<br>también cuenta.</h2><p>Comentarios compartidos con Confort4.</p></div>${link('resena.html','Compartir mi experiencia','button button-outline')}</div>${bundle.reviews?.length?`<div class="review-grid">${bundle.reviews.slice(0,3).map(r=>`<figure>${r.demo?'<p class="review-demo-label">Ejemplo visual · reseña ficticia</p>':''}<div class="review-rating" aria-label="${r.rating} de 5">${Array.from({length:r.rating},()=>icon('star')).join('')}</div><blockquote>${e(r.message)}</blockquote><figcaption>${e(r.name)}</figcaption></figure>`).join('')}</div>`:'<p class="review-invitation">Si ya trabajaste con el equipo, nos gustaría conocer tu experiencia. Publicamos únicamente comentarios revisados y autorizados.</p>'}</section>`;}
export function propertyDetail(bundle,p){
 const images=(p.imagenes||[]).map(i=>typeof i==='string'?i:i?.url).filter(Boolean);
 if(!images.length)images.push(imageOf(p));
 const rental=String(p.operacion).toLowerCase().includes('renta');
 const propertyType=String(p.tipo||'propiedad').toLowerCase();
 const operation=rental?'renta':'venta';
 const place=[p.colonia,p.municipio,p.estado].filter(Boolean).join(', ');
 const whatsapp='https://wa.me/525527477538?text='+encodeURIComponent('Hola, me interesa tu '+propertyType+' en '+operation+' en '+place+' que tienes publicado en Confort4.com. ¿Me puedes dar más información?\n'+new URL(propertyURL(p.id),'https://danyethxoxo.github.io/confort4/').href);
 const facts=[[p.recamaras,'Recámaras'],[p.banos,'Baños'],[p.estacionamientos,'Estacionamientos'],[p.m2_construccion||p.m2_terreno,'m² publicados']].filter(([value])=>Number(value)>0);
 const description=plain(p.descripcion);
 return `<section class="property-detail property-editorial wrap">
 <div class="property-gallery"><div class="property-photo-stage"><a class="property-back" href="propiedades.html">${icon('arrow')} Regresar</a><button type="button" class="property-gallery-cover" data-gallery-open aria-label="Abrir galería de ${images.length} fotos"><img id="gallery-main" src="${safeURL(images[0])}" alt="${e(p.titulo)}" width="1400" height="900" fetchpriority="high"><span>Ver ${images.length} fotos ${icon('plus')}</span></button><div class="property-detail-heading"><div><p class="property-eyebrow">${e(p.tipo||'Propiedad')} · ${e(p.operacion)}</p><h1>${e(p.titulo)}</h1><p class="property-location-line">${icon('map')}${e([p.colonia,p.municipio,p.estado].filter(Boolean).join(' · '))}</p></div><div class="property-price-block"><p class="property-price">${e(money(p.precio,p.moneda))}</p><span>${e(p.moneda||'MXN')}${rental?' / mes':''}</span></div></div></div><div class="property-thumbnail-carousel"><button type="button" class="thumbnail-arrow" data-thumbs-direction="-1" aria-label="Miniaturas anteriores">${icon('arrow')}</button><div class="property-gallery-thumbs" aria-label="Fotografías de la propiedad">${images.map((src,i)=>`<button type="button" data-gallery="${safeURL(src)}" aria-label="Ver foto ${i+1}" aria-pressed="${i===0}"><img src="${safeURL(src)}" alt="Foto ${i+1}" width="240" height="160" loading="lazy" decoding="async"></button>`).join('')}</div><button type="button" class="thumbnail-arrow" data-thumbs-direction="1" aria-label="Más miniaturas">${icon('arrow')}</button></div></div>
 <div class="property-detail-body"><div>${facts.length?`<dl class="property-key-facts">${facts.map(([value,label])=>`<div><dt>${e(label)}</dt><dd>${e(value)}</dd></div>`).join('')}</dl>`:''}<section class="property-overview"><h2>Conoce este espacio.</h2><div class="property-description" id="property-description">${(description||'Consulta los detalles de esta propiedad con el equipo.').split(/\n+/).filter(Boolean).map(t=>`<p>${e(t)}</p>`).join('')}</div>${description.length>900?'<button type="button" class="text-button" data-description-toggle aria-expanded="false" aria-controls="property-description" hidden>Leer descripción completa</button>':''}</section><section class="property-location-summary"><h2>La zona.</h2><iframe class="property-map" title="Mapa de la zona de ${e(p.colonia||p.municipio)}" src="https://maps.google.com/maps?q=${encodeURIComponent(place)}&amp;z=14&amp;output=embed" width="800" height="340" loading="lazy" referrerpolicy="no-referrer-when-downgrade" allowfullscreen data-lenis-prevent></iframe><p class="property-map-note">Ubicación aproximada</p><p>${e([p.colonia,p.municipio,p.estado].filter(Boolean).join(', '))}</p><a class="text-link" href="https://www.google.com/maps/search/?api=1&amp;query=${encodeURIComponent([p.colonia,p.municipio,p.estado].filter(Boolean).join(', '))}" target="_blank" rel="noopener">Explorar la zona ${icon('up')}</a></section></div><aside class="property-advisor"><div class="property-advisor-person"><img src="assets/alberto-renata-contacto.webp" alt="Alberto y Renata, Confort4" width="96" height="96" loading="lazy"><div><p>Alberto y Renata</p><h2>Confort4</h2></div></div><h3>¿Te interesa esta propiedad?</h3><a class="button" href="${safeURL(whatsapp)}" target="_blank" rel="noopener">Contáctanos ${icon('arrow')}</a>${kwAssociation()}</aside></div></section>
 <dialog class="property-viewer" aria-label="Fotografías de la propiedad"><div class="property-viewer-toolbar"><span data-gallery-count>1 / ${images.length}</span><button type="button" data-gallery-close aria-label="Cerrar visor">Cerrar ${icon('plus')}</button></div><div class="property-viewer-stage"><button type="button" data-gallery-step="-1" aria-label="Foto anterior">${icon('arrow')}</button><img data-gallery-full src="${safeURL(images[0])}" alt="${e(p.titulo)} · Foto 1"><button type="button" data-gallery-step="1" aria-label="Foto siguiente">${icon('arrow')}</button></div></dialog>`;
}
export function comparisonTable(service){const c=service.comparison;if(!c?.rows?.length)return '';return `<section class="comparison-module service-comparison wrap"><h2>${e(c.title)}</h2><table><caption class="sr-only">${e(c.soloLabel)} y acompañamiento con Confort4</caption><thead><tr><th scope="col"><span class="sr-only">Aspecto</span></th><th scope="col">${e(c.soloLabel)}</th><th scope="col">Con Confort4</th></tr></thead><tbody>${c.rows.map(r=>`<tr><th scope="row">${e(r[0])}</th><td data-label="${e(c.soloLabel)}">${e(r[1])}</td><td data-label="Con Confort4"><span class="comparison-check">${icon('check')}</span><span>${e(r[2])}</span></td></tr>`).join('')}</tbody></table></section>`;}
export function googleReviewModule(data){const g=data.googleReviews;if(!g?.items?.length)return '';return `<section class="reviews-module google-reviews wrap" aria-labelledby="google-reviews-title"><div class="module-heading"><div><h2 id="google-reviews-title">Sus experiencias,<br>en Google.</h2><p>${e(g.rating.toFixed(1))} de 5 · ${e(g.total)} opiniones · Google</p></div><a class="text-link" href="${safeURL(g.url)}" target="_blank" rel="noopener">Ver perfil en Google ${icon('arrow')}</a></div><div class="review-carousel" role="region" aria-label="Reseñas de Google"><div class="review-grid">${g.items.map((r,index)=>`<figure data-review-slide ${index>=3?'hidden':''}><div class="review-rating" aria-label="${e(r.rating)} de 5">${Array.from({length:r.rating},()=>icon('star')).join('')}</div><blockquote>${e(r.message)}</blockquote><button type="button" class="text-button review-read" data-review-read>Leer reseña</button><figcaption>${e(r.name)}<span>Google${r.excerpt?' · Fragmento':''}</span></figcaption></figure>`).join('')}</div><div class="review-controls"><span data-review-count aria-live="polite">1–${Math.min(3,g.items.length)} / ${g.items.length}</span><button type="button" data-review-direction="-1" aria-label="Reseña anterior">${icon('arrow')}</button><button type="button" data-review-direction="1" aria-label="Siguiente reseña">${icon('arrow')}</button></div></div><dialog class="review-full-dialog" aria-labelledby="review-full-title"><button type="button" data-review-close aria-label="Cerrar reseña">Cerrar ${icon('plus')}</button><h2 id="review-full-title"></h2><blockquote></blockquote><p>Google</p></dialog><p class="google-review-date">Consulta del 13 de noviembre de 2026.</p></section>`;}
export function renderPage(bundle,page,params={}){
 const d=bundle.content,properties=bundle.properties||[];
 if(page==='home'){
  const modules={intents:()=>intents(d),properties:()=>propertyModule(bundle),process:()=>processModule(d)+livingScene(bundle),journal:()=>journal(d),faq:()=>faqModule(d),contact:()=>contactForm(d),reviews:()=>`<section class="review-form-layout wrap home-review" id="resena"><div><h2>Cuéntanos tu experiencia.</h2><p>Leemos cada reseña. Solo la publicamos con tu autorización y después de revisarla.</p></div>${reviewForm}</section>`};
  return `<section class="hero wrap"><div class="hero-visual"><img class="hero-image" src="${safeURL(d.home.photo)}" alt="Fachada arquitectónica de ambientación" width="1920" height="1280" fetchpriority="high"></div><div class="hero-content"><h1>${e(d.home.title)}</h1><div class="hero-aside"><p>${e(d.home.intro)}</p>${link('contacto.html','Hablemos de tu proyecto','button')}</div></div></section>
  <section class="brand-statement wrap"><p class="scroll-copy">${e(d.team.intro)}</p>${link('quienes-somos.html','Conoce a Alberto y Renata')}${kwAssociation()}</section>
  ${d.home.modules.map(module=>modules[module]?.()||'').join('')}${googleReviewModule(d)}`;

 }
 if(['vender','comprar','rentar'].includes(page)){
  const s=d.services.find(s=>s.id===page);const audience=page==='rentar'?`<section class="rental-audiences wrap">${s.audiences.map(a=>`<article id="${a.id}"><h2>${e(a.title)}</h2><p>${e(a.intro)}</p><ul>${a.items.map(t=>`<li>${e(t)}</li>`).join('')}</ul>${link(contactURL('rentar-'+a.id),'Quiero acompañamiento')}</article>`).join('')}</section>`:'';
  return `<section class="page-intro service-page-intro wrap"><div>${link('index.html','Inicio','breadcrumb')}<h1>${e(s.title)}</h1><p>${e(s.intro)}</p>${link(contactURL(page==='rentar'?'general':page),s.cta,'button')}</div><img src="${safeURL(s.image)}" alt="${e(s.imageAlt||'Espacio residencial de ambientación')}" width="1100" height="733"></section>${audience}${comparisonTable(s)}${processModule(d,page==='rentar'?'general':page)}${page==='vender'?'':`<div class="wrap">${checklist(d,page==='comprar'?'visita':'renta')}</div>`}<section class="service-reading wrap"><h2>Antes de dar el siguiente paso.</h2><div>${s.sections.map(b=>`<details><summary>${e(b.title)}${icon('plus')}</summary><p>${e(b.text)}</p></details>`).join('')}</div></section>${faqModule({...d,faq:d.faq.filter(f=>f.category===s.shortTitle||f.category==='Proceso')})}<section class="page-cta wrap"><div><h2>Demos forma a tu proyecto.</h2><p>${e(s.closing)}</p></div>${link(contactURL(page==='rentar'?'general':page),'Contactar a Confort4','button')}</section>`;
 }
 if(page==='team')return teamPage(bundle);
 if(page==='contact')return contactForm(d,true);
 if(page==='catalog')return `<section class="page-intro wrap"><h1>Tu próximo espacio,<br>más cerca.</h1><p>Conoce las propiedades seleccionadas por Confort4. Guarda tus favoritas y consulta su disponibilidad con el equipo.</p></section>${propertyModule(bundle,true)}${contactForm(d)}`;
 if(page==='property'){
  const p=properties.find(p=>p.id===params.id);if(!p)return `<section class="page-intro wrap"><h1>Esta propiedad ya no está en el catálogo.</h1><p>Podemos ayudarte a encontrar otras opciones.</p>${link('propiedades.html','Explorar propiedades','button')}</section>`;
  return propertyDetail(bundle,p);
 }
 if(page==='blog')return `<section class="page-intro wrap"><h1>Más información.<br>Mejores preguntas.</h1><p>Guías y herramientas para avanzar con claridad en tu proyecto inmobiliario.</p></section>${journal(d,true)}`;
 if(page==='article'){
  const post=availablePosts(d).find(p=>p.slug===params.slug);if(!post)return `<section class="page-intro wrap"><h1>Esta lectura no está disponible.</h1>${link('blog.html','Volver al blog','button')}</section>`;
  return `<article class="editorial-article wrap">${link('blog.html','Todas las lecturas','breadcrumb')}<header><h1>${e(post.title)}</h1><p class="article-deck">${e(post.excerpt)}</p><p class="article-meta">${e(post.author)} · Actualizado ${e(post.updated)} · ${Math.max(1,Math.ceil(JSON.stringify(post.sections).split(/\s+/).length/200))} min de lectura</p></header><img class="article-cover" src="${safeURL(post.cover)}" alt="Imagen de ambientación" width="1400" height="800"><div class="editorial-layout"><aside class="article-toc"><nav aria-label="En esta lectura"><strong>En esta lectura</strong>${post.sections.map((s,i)=>`<a href="#lectura-${i}">${e(s.title)}</a>`).join('')}</nav></aside><div class="editorial-body"><div class="article-takeaways"><h2>En pocas palabras.</h2><ul>${post.summary.map(t=>`<li>${e(t)}</li>`).join('')}</ul></div>${post.sections.map((s,i)=>`<section id="lectura-${i}"><h2>${e(s.title)}</h2><p>${e(s.text)}</p></section>`).join('')}${post.source?`<p class="article-source">Para ampliar: <a href="${safeURL(post.source.url)}" target="_blank" rel="noopener">${e(post.source.label)}</a></p>`:''}</div></div></article>${post.checklist?`<div class="wrap">${checklist(d,post.checklist)}</div>`:''}<section class="page-cta wrap"><h2>Hablemos de tu caso.</h2>${link('contacto.html','Contactar a Confort4','button')}</section>${journal({...d,posts:availablePosts(d).filter(p=>p.slug!==post.slug)})}`;
 }
 if(page==='resources')return `<section class="page-intro wrap"><h1>Prepararte también<br>es avanzar.</h1><p>Herramientas prácticas para ordenar información y llevar mejores preguntas a tu proyecto.</p></section><div class="wrap">${checklist(d,'venta')}${checklist(d,'visita')}${checklist(d,'renta')}</div>`;
 if(page==='faq')return `<section class="page-intro wrap"><h1>Una duda menos.<br>Un paso más.</h1></section>${faqModule(d,true)}`;
 return '';
}
